    if rel.split(os.sep)[0] not in ('ayah','surah'): continue
    for f in files:
        p=os.path.join(root,f); tail=f'{rel}/{f}'.replace(os.sep,'/'); h=open(p).read()
        if 'rel="alternate" hreflang' not in h: open(p,'w').write(h.replace('</head>',alts(tail)+'</head>',1))
